#!/usr/bin/env python3
"""Write stills/jobs.json for the 15 trailer stills (Krea 2 Turbo). Design strings word for word from script_v2.md."""
import json
from pathlib import Path
P = Path(__file__).resolve().parent.parent
PRE = (P / "look_test/PREFIX.txt").read_text().strip()
ENV = PRE + " Empty of characters and creatures, no animals."
HANK = ("Hank, a huge round gentle grizzly bear with thick dark chocolate-brown fur painted as soft dense brush marks, a lighter tan muzzle, "
        "small round ears, kind dark-brown eyes, no clothing, no collar, no hat; smooth dense fur, no feather shapes, no wings")
YHANK = HANK + ", a little smaller and rounder than full-grown"
DOUG = ("Doug, a sturdy heavy-built bloodhound with a deep chest, one solid russet-red coat all over, very long droopy velvet ears in the same "
        "russet a shade darker, deep wrinkles over his forehead, droopy eyes, a big black nose, a worn dark-brown leather collar with one small "
        "brass ring; no black saddle, no white legs, no white chest")
WAGON = ("a big red-painted wooden fire-wagon with ochre-gold trim on four huge spoked wooden wheels with iron rims, a plank bench up front, "
         "a dented old brass hand lantern hanging from an iron hook on the front post beside the bench, a coiled canvas hose and a brass "
         "hand-pump lever at the back, no engine, no tires, no cab, no roof")
TEAM = ("a single line of four harnessed animals pulling in front of the wagon, nose to tail: one chestnut horse, one black-and-white striped "
        "zebra, one tan one-humped camel, one black-and-white dairy cow, all in brown leather harness; four heads, four bodies")
GIR = "two tall friendly reticulated giraffes with orange-brown patch patterns on cream, short ossicone horns, long dark lashes"
ELE = "two big friendly grey African elephants with huge ears, each carrying an oak water barrel strapped on its back"
GOAT = "a small white nanny goat with short grey horns, a little white beard and grey knees"
MARMOT = "a plump yellow-brown marmot with a cream belly, small round ears and buck teeth"
GEESE = "a dozen big white domestic geese with orange beaks and feet"
TURTLE = "a green-brown pond turtle with a yellow-striped neck and a domed shell"
KITTEN = "a tiny grey tabby kitten with big round green eyes and a pink nose"
OTTERS = "four sleek dark-brown river otters with pale throats and long tapered tails"
CHIP = "a small chipmunk, orange-brown with five dark stripes down its back and white cheeks"
LANT = "a dented old brass hand lantern with a glass panel, warm amber flame"
# fixes from the look test, stated as facts of the picture (not new adjectives on the design strings)
DOUGFIX = " Doug's back, shoulders and sides are the same solid russet red as the rest of him, one single color, no black patch anywhere."
HANKFIX = " Hank's chest and belly fur is smooth dense brush marks like the rest of his coat, no overlapping feather-like or scale-like shapes."
CAMELFIX = " The camel has exactly one hump."
S = {}
S["A_ledge_goat"] = (PRE + f" Wide shot of a grey granite mountain face at dawn, a narrow rock ledge high up with a sheer drop below, thin dawn light from the upper right, cool shadow on the rock face, slate-blue haze in the valley far below. On the ledge stands GOAT, {GOAT}, four feet bunched together, head turned down toward the viewer, mouth open mid-bleat. Nothing else on the ledge, no other animals. Cinematic composition, the goat small in the upper third of the frame.")
S["B_marmot"] = (PRE + f" Medium shot in a sage-green alpine meadow, the grey mountain soft and out of focus behind, morning sun as the key from the upper left, warm light on a big sun-warmed boulder. On top of the boulder MARMOT, {MARMOT}, stands tall on her hind legs, chest out, head up, mouth a small round O, whistling. No other animals. Cinematic composition.")
S["C_bench"] = (PRE + f" Medium two-shot, three-quarter front, of two animals sitting side by side on the plank bench of WAGON, {WAGON}, parked on a dirt road under big oaks. On the left sits Doug, {DOUG}. On the right sits Hank, {HANK}. Hank is twice Doug's size.{DOUGFIX}{HANKFIX} Doug's long ears lift and swing forward as his head turns toward a far-off sound; Hank's head is turned in profile looking down the road, his big paw closing around the leather reins; the dented brass lantern hangs unlit on the iron hook on the front post beside Hank. Soft morning sun as the key from the upper left, 45 degrees off camera, filtered through oak leaves, warm dappled light on the far side of both faces, cool open shade on the camera side, soft painted haze in the background trees. Cinematic composition.")
S["D_rollout"] = (PRE + f" Wide shot, clean side profile, camera low beside a dirt road through rolling sage-green hills. From left to right in one line: TEAM, {TEAM}, then WAGON behind them, {WAGON}, with Hank, {HANK} and Doug, {DOUG} sitting small on the bench, then GIRAFFES, {GIR}, jogging alongside at the back on the far side of the road, and ELEPHANTS, {ELE}, walking behind the wagon. Dust drifts behind the wheels.{DOUGFIX}{CAMELFIX} A single wagon, the only vehicle on the road; nobody and nothing else rides on the wagon except Hank and Doug on the front bench, the wagon bed behind them holds only the coiled hose; the only animals in the picture are the four team animals, Hank, Doug, the two giraffes and the two elephants; no loose animals, no second wagon, exactly as many heads as bodies. Low morning sun from behind the camera's right, 50 degrees off axis, long soft shadows across the road, backlit painted dust haze, hills in soft painted layers. Cinematic composition.")
S["E_turtle"] = (PRE + f" Medium-wide shot of a shrunken pond in a dry meadow, the water pulled back to a small muddy puddle, the mud around it cracked into plates, drying grey-brown. In the middle TURTLE, {TURTLE}, is sunk to the rim of his shell in thick mud, four legs paddling and going nowhere, head stretched up. Hard midday sun from high left, hot light on the cracked mud, the turtle's shell in half shadow. No other animals. Cinematic composition.")
S["F_drain"] = (PRE + f" Shot looking straight down through the bars of an iron storm-drain grate set in old cobblestones at the edge of a quiet lane; no people, no vehicles, no signs. Two meters below the bars, small in a shallow puddle at the bottom of the shaft, KITTEN, {KITTEN}, looks straight up at the viewer, mouth open in a mew. Cool overcast light from above through the bars, the shaft dark and damp, a few bars of light on the kitten. No other animals. Cinematic composition.")
S["G_forest"] = (PRE + f" Wide shot of a night forest road in cold moonlight, silver-blue, tall trunks, a fallen log across the trail ahead. Walking along the trail toward the left, nose down to the ground, DOUG, {DOUG}, a little smaller than full-grown.{DOUGFIX} From off-frame to the right behind him a warm amber lantern glow spills across the ground and the trunks, following him; the lantern itself and whoever holds it are outside the frame, not visible. Ahead of Doug, half hidden behind the fallen log, crouches YOUNG HANK, {YHANK}, eyes wide, ears flat.{HANKFIX} No humans, no hands, no boots, no gun, no visible lantern. Cool moonlight as the key from the upper left, the warm glow as a low rim light from the right. Cinematic composition.")
S["H1_ditch"] = (ENV + " Low wide shot of a muddy roadside ditch at the edge of a dark forest at night in cold moonlight, silver-blue; a shallow puddle in the ditch, wet mud, tufts of grass, and the empty dirt road running away into the background between the trees. Nothing in the ditch. Moonlight as the key from the upper left. Cinematic composition.")
S["H2_lantern"] = (PRE + f" Product-style painting of one object alone, centered, on a plain flat dark slate-blue background with nothing else: LANTERN, {LANT}, hanging from its handle, the flame lit, warm amber light on the brass. No hands, no people, no other objects. Centered composition, the lantern filling most of the frame height.")
S["I_walkaway"] = (PRE + f" Wide shot from behind, a moonlit dirt road running away into silver hills under a night sky that thins toward a warm sky at the top of the frame. Walking away from the camera down the road, side by side, seen from behind: DOUG, {DOUG}, a little smaller than full-grown, tail up, and YOUNG HANK, {YHANK}, a head taller than Doug.{DOUGFIX}{HANKFIX} No one else on the road, no lantern, no humans. Cool moonlight as the key from behind the camera, a warm glow on the horizon. Cinematic composition, the pair small in the lower third.")
S["J_title_hill"] = (PRE + f" Wide shot of a warm ochre-and-rust sunset sky over sage-green rolling hills. On the hilltop, in dark silhouette against the sunset, in clean side profile: TEAM, {TEAM}, pulling WAGON, {WAGON}, with GIRAFFES, {GIR}, walking behind; all in flat dark silhouette, one tiny amber point of light on the wagon's front post.{CAMELFIX} No text, no letters, no sign. The sky fills the upper two thirds, empty, for a title. Cinematic composition.")
S["K_sleeping"] = (PRE + f" Medium-wide shot under a big oak at golden sunset, WAGON, {WAGON}, parked, everyone asleep in a pile: Hank, {HANK}, slumped on the bench, head back, eyes shut, mouth slightly open; Doug, {DOUG}, sprawled asleep across Hank's lap, long ears hanging to the floorboards; one giraffe neck of GIRAFFES, {GIR}, drooping asleep over the wagon from behind; MARMOT, {MARMOT}, curled asleep on top of Hank's head; on the front post the dented brass lantern lit, warm amber, the one light in the dusk.{DOUGFIX}{HANKFIX} In the foreground, on the rim of the near wheel, CHIPMUNK, {CHIP}, sits up alert, mouth open in a squeak. No other animals. Warm low sunset as the key from the right, the lantern as a small warm practical, cool blue dusk shadow on the camera side. Cinematic composition.")
S["L_airlift"] = (PRE + f" Wide shot up a grey granite mountain face at dawn, the narrow rock ledge with GOAT, {GOAT}, stepping with her front hooves onto a flat wooden plank platform that hangs level with the ledge, held up by four ropes from its corners; the ropes are held in the beaks of GEESE, {GEESE}, flying above with wings beating. Thin dawn light from the upper right, slate-blue haze below. Exactly one goat, no other animals besides the geese. Cinematic composition.")
S["M_otters"] = (PRE + f" Medium shot at eye level with old cobblestones at the edge of a quiet lane, an iron storm-drain grate flipped open beside a dark square hole. A chain of OTTERS, {OTTERS}, hangs down into the hole, each otter holding the hind feet of the one below; at the top of the frame only the two big forearms and paws of Hank, {HANK}, dark chocolate-brown fur, hold the top otter's hind feet, the rest of the bear out of frame. The bottom otter is rising out of the hole holding KITTEN, {KITTEN}, gently by the scruff, the kitten's eyes wide, legs dangling. No people, no vehicles, no signs. Soft overcast light from above, cool shadow in the hole. Cinematic composition.")
S["N_nose"] = (PRE + f" Close two-shot in cold silver-blue moonlight, side-on, over the top of a fallen log in a night forest: on the left the face of DOUG, {DOUG}, a little smaller than full-grown; on the right the face of YOUNG HANK, {YHANK}, eyes wide and scared, ears flat; their noses almost touching.{DOUGFIX}{HANKFIX} Only the two faces and the log, no one else, no lantern. Cool moonlight as the key from the upper left, soft fill, dark trunks out of focus behind. Cinematic composition.")
HERO = {"C_bench": [1102, 1103], "D_rollout": [1102, 1104], "K_sleeping": [1101, 1102], "N_nose": [1101, 1102], "G_forest": [1101], "I_walkaway": [1101]}
jobs = []
for name, prompt in S.items():
    for seed in HERO.get(name, [1101]):
        tag = f"{name}_s{seed}" if name in HERO else name
        jobs.append({"out": str(P / f"stills/{tag}.png"), "w": 1344, "h": 768, "seed": seed, "steps": 12 if name in HERO else 8, "prompt": prompt})
(P / "stills/jobs.json").write_text(json.dumps(jobs, indent=1))
print(len(jobs), "jobs")
